import {BrowserRelay} from './transport.js';
import {evaluate} from './model.js';
import {installTour} from './tour.js';
const $=s=>document.querySelector(s), config={tls:false,auth:false,origin:false,integrity:false};
const descriptions={tls:['TLS transport','Models protection against on-path listening and edits.'],auth:['Authentication','Rejects synthetic unauthenticated senders.'],origin:['Origin validation','Rejects synthetic foreign website connections.'],integrity:['End-to-end integrity','Models recipient verification; detects relay edits.']};
for(const [key,[name,help]] of Object.entries(descriptions)){const el=document.createElement('div');el.className='defense';el.innerHTML=`<label><input id="${key}" type="checkbox">${name}</label><p>${help}</p>`;$('#defenses').append(el);el.querySelector('input').onchange=e=>{config[key]=e.target.checked;event('policy',`${name}: ${config[key]?'enabled':'disabled'} (modeled)`);updateThreat()}}
let tourRun="",socket,pending=null,seq=0,epoch=0,events=[],records=[],attempts=[],waiting=new Map(),latencies=[];
function event(type,detail){events.push({time:new Date().toISOString(),type,detail});events=events.slice(-100);const li=document.createElement('li');li.textContent=`${new Date().toLocaleTimeString()} · ${type} · ${detail}`;$('#events').prepend(li);while($('#events').children.length>100)$('#events').lastChild.remove()}
function connect(){socket=new BrowserRelay();$('#connection').textContent='Connecting…';socket.onopen=()=>{$('#connection').textContent='● Browser-local simulation ready';event('open','Browser-local relay initialized. No network connection is opened.');facts()};socket.onclose=e=>{$('#connection').textContent='○ Disconnected · retrying in 2s';event('close',`Transport closed (${e.code}). In-flight messages are marked failed.`);for(const m of waiting.values())finish(m,'failed','Transport disconnected');waiting.clear();setTimeout(connect,2000)};socket.onerror=()=>event('error','Browser-local relay error');socket.onmessage=e=>{const frame=JSON.parse(e.data);const m=waiting.get(frame.id);if(!m||m.epoch!==epoch)return;$('#frame').textContent=JSON.stringify(frame,null,2);event('message',`Local simulated JSON envelope · ${new TextEncoder().encode(e.data).length} bytes`);waiting.delete(frame.id);clearTimeout(m.timeout);if(m.epoch!==epoch)return;latencies.push(performance.now()-m.started);bubble(m.to,frame.payload,false,m.changed,m.runLabel);finish(m,'delivered',m.reason)}}
function facts(){$('#facts').textContent=`Mode: browser-local simulation\nRelay: MessageChannel, isolated to this page\nReady state: ${socket.readyState} (ready = 1)\nEnvelope: synthetic JSON {type, id, payload}\nModeled transport: ${config.tls?'TLS protection enabled':'plaintext transport'}\nActual network traffic: none from this lab\nTiming: local event-loop round trip, not network latency\nNo real packets, credentials or TLS frames are captured.`;}
function bubble(who,text,sent,changed=false,runLabel=""){const box=$('#messages'+who);box.querySelector('.empty')?.remove();const div=document.createElement('div');div.className='bubble'+(sent?' sent':'')+(changed?' modified':'');const meta=document.createElement('small');meta.textContent=(runLabel?runLabel+' · ':'')+(sent?'SENT':'RECEIVED')+(changed?' · MODIFIED':'');div.append(meta,document.createTextNode(text));box.append(div);while(box.children.length>50)box.firstChild.remove();box.scrollTop=box.scrollHeight}
function busy(on){const guided=document.body.classList.contains('guided-mode');$('#route').textContent=on?'MESSAGE PAUSED / INSPECT':'BROWSER-LOCAL RELAY';$('.flow').classList.toggle('paused',on);for(const id of ['view','forward','tamper','drop'])$('#'+id).disabled=!on;for(const id of ['inputA','inputB'])$('#'+id).closest('form').querySelector('button').disabled=on||guided;$('#threat').disabled=on||guided;for(const key in config)$('#'+key).disabled=on||guided}
function updateThreat(){const threat=$('#threat').value;$('#threatHelp').textContent={network:'An observer between endpoint and relay. TLS can conceal the modeled payload.',relay:'Inside the relay, after transport TLS terminates. TLS cannot protect against this observer.',anonymous:'A synthetic sender without a valid credential. Authentication determines admission.','cross-origin':'A synthetic browser connection from another website. Origin validation determines admission.'}[threat];if(socket?.readyState===1)facts()}
function send(from){if(pending){return}if(socket.readyState!==1){$('#outcome').textContent='Transport not connected. Wait for reconnection.';return}const input=$('#input'+from),text=input.value.trim();if(!text)return;const m={id:++seq,epoch,runLabel:tourRun,from,to:from==='A'?'B':'A',original:text,config:{...config},threat:$('#threat').value,created:performance.now()};bubble(from,text,true,false,tourRun);records.push(m);event('send',`#${m.id} ${from} → ${m.to}: ${new TextEncoder().encode(text).length} UTF-8 payload bytes`);const admission=evaluate(m.config,m.threat,'forward');if(admission.status==='blocked'&&['anonymous','cross-origin'].includes(m.threat)){attempts.push({action:m.threat,status:'blocked'});finish(m,'blocked',admission.reason);return m}if(['anonymous','cross-origin'].includes(m.threat))attempts.push({action:m.threat,status:'success'});if($('#intercept').checked){pending=m;busy(true);$('#pendingLabel').textContent=`#${m.id} paused · ${from} → ${m.to} · policy snapshot`;const concealed=m.threat==='network'&&m.config.tls;$('#edit').disabled=concealed;$('#edit').value=concealed?'[TLS ciphertext — payload unavailable to network observer]':text;$('#outcome').textContent='Message paused in the synthetic interception sandbox.';event('pause',`#${m.id}: ${m.threat}`)}else relay(m,text,false,'Message delivered without interception.');render();return m;}
for(const from of ['A','B'])$('#form'+from).onsubmit=e=>{e.preventDefault();send(from)};
function release(){pending=null;busy(false);$('#edit').disabled=true;$('#edit').value='';$('#pendingLabel').textContent='Waiting for a message'}
function act(action){if(!pending)return;const m=pending,edited=$('#edit').value,changed=action==='edit'&&edited!==m.original;if(action==='edit'&&!changed){$('#outcome').textContent='Change the intercepted payload before choosing Edit & forward.';return}const result=evaluate(m.config,m.threat,action,changed);const attack=action!=='forward';if(attack)attempts.push({action,status:result.status==='blocked'?'blocked':'success'});event(action,`#${m.id} · ${result.reason}`);$('#outcome').textContent=result.reason;if(action==='view'){render();return}release();if(result.status==='delivered')relay(m,changed?edited:m.original,changed,result.reason);else finish(m,result.status,result.reason)}
$('#view').onclick=()=>act('view');$('#forward').onclick=()=>act('forward');$('#tamper').onclick=()=>act('edit');$('#drop').onclick=()=>act('drop');
function relay(m,payload,changed,reason){$('.flow').classList.add('moving');setTimeout(()=>$('.flow').classList.remove('moving'),700);m.started=performance.now();m.changed=changed;m.reason=reason;waiting.set(m.id,m);m.timeout=setTimeout(()=>{if(waiting.delete(m.id))finish(m,'failed','Transport timeout; no delivery acknowledgement.')},5000);try{socket.send(JSON.stringify({type:'relay',id:m.id,payload}));event('frame',`#${m.id} simulated outbound JSON envelope`)}catch{waiting.delete(m.id);clearTimeout(m.timeout);finish(m,'failed','Transport send failed.')}}
function finish(m,status,reason){if(m.status)return;m.status=status;m.reason=reason;m.resolved=performance.now();if(m.runLabel&&['blocked','dropped','failed'].includes(status)){const note=document.createElement('div');note.className='delivery-note';note.textContent=m.runLabel+' · '+(status==='blocked'?'REJECTED — no message delivered':status==='dropped'?'LOST — no message delivered':'Transport failed');$('#messages'+m.to).append(note);$('#messages'+m.to).scrollTop=$('#messages'+m.to).scrollHeight;}$('#outcome').textContent=reason;event(status,`#${m.id}: ${reason}`);render()}
function render(){const n=status=>records.filter(x=>x.status===status).length;const avg=latencies.length?(latencies.reduce((a,b)=>a+b,0)/latencies.length).toFixed(1)+' ms':'—';const vals=[['Sent',records.length],['Delivered',n('delivered')],['Blocked / dropped',`${n('blocked')} / ${n('dropped')}`],['Attack success',attempts.length?Math.round(attempts.filter(x=>x.status==='success').length/attempts.length*100)+'%':'—'],['Local relay RTT',avg]];$('#metrics').replaceChildren();for(const [label,value]of vals){const div=document.createElement('div');div.className='metric';const strong=document.createElement('strong');strong.textContent=value;const span=document.createElement('span');span.textContent=label;div.append(strong,span);$('#metrics').append(div)}
const complete=records.filter(x=>x.status),max=Math.max(1,complete.length);let svg='';for(let i=0;i<5;i++){const y=160-i*35;svg+=`<line x1="30" y1="${y}" x2="620" y2="${y}" stroke="#ffffff12"/><text x="0" y="${y+4}" fill="#a9bbce" font-size="10">${Math.round(max*i/4)}</text>`}for(const [status,color]of [['delivered','#a4e4d2'],['blocked','#f1a9bd'],['dropped','#e9c289']]){let count=0;const pts=['30,160'];complete.forEach((r,i)=>{if(r.status===status)count++;pts.push(`${30+(i+1)/max*590},${160-count/max*140}`)});svg+=`<polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`}svg+='<text x="30" y="185" fill="#a9bbce" font-size="10">0</text><text x="515" y="185" fill="#a9bbce" font-size="10">Resolved message index →</text>';$('#chart').innerHTML=svg;$('#chartSummary').textContent=`${complete.length} resolved · ${records.length-complete.length} pending · ${n('failed')} transport failures. RTT measures local simulation round trip, excluding interception dwell time.`;
$('#bars').replaceChildren();for(const [name,status,color]of [['Succeeded','success','#a4e4d2'],['Prevented','blocked','#f1a9bd']]){const count=attempts.filter(a=>a.status===status).length;const row=document.createElement('div');row.className='bar-row';row.innerHTML=`<span>${name}</span><div class="bar-track"><div class="bar-fill"></div></div><span>${count}</span>`;$('#bars').append(row)}// use CSSOM for CSP-compliant dynamic widths
for(const row of $('#bars').children){const fill=row.querySelector('.bar-fill');const count=Number(row.lastChild.textContent);fill.style.width=(attempts.length?count/attempts.length*100:0)+'%';fill.style.background=row.firstChild.textContent==='Prevented'?'#f1a9bd':'#a4e4d2'}
}
$('#threat').onchange=updateThreat;$('#secure').onclick=()=>{if(pending){$('#outcome').textContent='Resolve the paused message before changing defenses.';return}for(const key in config){config[key]=true;$('#'+key).checked=true}updateThreat();event('policy','All modeled defenses enabled')};$('#reset').onclick=()=>{epoch++;for(const m of waiting.values())clearTimeout(m.timeout);waiting.clear();pending=null;release();records=[];attempts=[];events=[];latencies=[];$('#events').replaceChildren();$('#frame').textContent='No frames received yet.';for(const who of ['A','B'])$('#messages'+who).replaceChildren();$('#outcome').textContent='Session cleared. Current defense settings retained.';event('reset','New session');render()};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({provenance:'2026 synthetic session, not original 2022 results',config,records:records.map(({timeout,...r})=>r),attempts,events},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='security-lab-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
updateThreat();render();connect();





installTour({config, setTourRun:label=>tourRun=label, send, act, updateThreat, release, finish, event, pending:()=>pending, abortInFlight:()=>{for(const m of waiting.values()){clearTimeout(m.timeout);finish(m,'failed','Operator left the scenario before its acknowledgement.');}waiting.clear();}, syncBusy:()=>busy(Boolean(pending))});
